/* Smoke test for app.js using a minimal DOM stub. Not part of the deliverable. */
const fs = require('fs');
const code = fs.readFileSync('/tmp/claude-1000/-home-arda-projects-agent-evaluation/8413ce30-b544-4ae4-afd6-5f8333042ec1/scratchpad/agent-eval-step-5-preview/13-frontend-playful/app.js', 'utf8');

function makeEl(tag = 'div') {
  const el = {
    tagName: tag, children: [], attributes: {}, dataset: {},
    hidden: false, textContent: '', _innerHTML: '', offsetWidth: 0,
    style: { setProperty() {} },
    _listeners: {},
    classList: { add() {}, remove() {}, contains() { return false; } },
    setAttribute(k, v) { this.attributes[k] = String(v); },
    getAttribute(k) { return k in this.attributes ? this.attributes[k] : null; },
    replaceChildren(...kids) { this.children = kids; },
    addEventListener(type, fn) { (this._listeners[type] ||= []).push(fn); },
    querySelector() { return null; },
    focus() {},
  };
  Object.defineProperty(el, 'innerHTML', {
    get() { return this._innerHTML; },
    set(v) { this._innerHTML = String(v); this.children = []; },
  });
  return el;
}

const byId = {};
['plant-list', 'today-date', 'greeting', 'progress', 'progress-fill', 'progress-count', 'queue-hint',
 'queue-heading', 'done-state', 'done-title', 'done-msg', 'reset-day', 'snooze-corner', 'snooze-list',
 'rhythm-figure', 'rhythm-caption', 'notes-body', 'toast', 'toast-msg', 'toast-undo']
  .forEach((id) => { byId[id] = makeEl(); });

global.document = {
  _listeners: {},
  querySelector(sel) { return sel.startsWith('#') ? byId[sel.slice(1)] || null : null; },
  getElementById(id) { return byId[id] || null; },
  createElement: makeEl,
  addEventListener(type, fn) { (this._listeners[type] ||= []).push(fn); },
};

eval(code);

const assert = (cond, msg) => { if (!cond) { console.error('FAIL:', msg); process.exitCode = 1; } else console.log('ok:', msg); };
const click = (id, action, controls = 'detail-' + id) => {
  const btn = {
    attributes: { 'aria-controls': controls, 'aria-expanded': 'false' },
    dataset: { action },
    setAttribute(k, v) { this.attributes[k] = String(v); },
    getAttribute(k) { return this.attributes[k]; },
    closest(sel) { return sel === 'button[data-action]' ? btn : { dataset: { id } }; },
  };
  document._listeners.click.forEach((fn) => fn({ target: btn }));
  return btn;
};

// initial render
assert(byId['progress'].attributes['aria-valuenow'] === '0', 'progress starts at 0');
assert(byId['plant-list'].children.length === 4, 'queue has 4 plants');
assert(byId['plant-list'].children[0].dataset.id === 'fern', 'overdue fern sorts first');
assert(byId['plant-list'].children[0].className.includes('plant--overdue'), 'fern marked overdue');
assert(byId['plant-list'].children[3].dataset.id === 'calathea', 'calathea sorts last');
assert(byId['queue-hint'].textContent.includes('Frida'), 'hint prioritises overdue');
assert(byId['done-state'].hidden === true, 'all-done hidden while queue exists');
assert(byId['rhythm-figure'].innerHTML.includes('<ellipse'), 'rhythm svg has leaves');
assert(byId['rhythm-figure'].innerHTML.includes('aria-label="Care rhythm'), 'rhythm has text alternative');
assert(byId['notes-body'].innerHTML.includes('Frida'), 'notes show featured plant');

// water the fern
click('fern', 'water');
assert(byId['progress'].attributes['aria-valuenow'] === '1', 'progress becomes 1 after watering');
assert(byId['plant-list'].children.length === 3, 'queue drops to 3');
assert(byId['plant-list'].children[0].dataset.id === 'pothos', 'pothos now first');
assert(byId['toast'].hidden === false && byId['toast-msg'].textContent.includes('Frida is watered'), 'toast confirms with reaction');
assert(byId['toast-undo'].hidden === false, 'undo offered');

// undo
byId['toast-undo']._listeners.click.forEach((fn) => fn());
assert(byId['progress'].attributes['aria-valuenow'] === '0', 'undo restores progress');
assert(byId['plant-list'].children.length === 4 && byId['plant-list'].children[0].dataset.id === 'fern', 'undo restores queue');

// snooze the fern
click('fern', 'snooze');
assert(byId['snooze-corner'].hidden === false, 'snooze corner shown');
