let depth = 0, line = 1, bad = false;
for (const ch of css) {
  if (ch === '\n') line++;
  if (ch === '{') depth++;
  if (ch === '}') { depth--; if (depth < 0) { bad = true; console.log('unbalanced } at line', line); } }
}
