const html = fs.readFileSync('index.html','utf8');
const voids = new Set(['meta','link','br','hr','img','input','source','path','circle','rect','ellipse','use']);
const stack = [];
for (const m of html.matchAll(/<(\/?)([a-zA-Z][a-zA-Z0-9-]*)((?:\"[^\"]*\"|'[^']*'|[^'\">])*)>/g)) {
  const [, close, tag] = m;
  if (voids.has(tag.toLowerCase()) || m[0].endsWith('/>')) continue;
  if (close) {
    const top = stack.pop();
    if (top !== tag.toLowerCase()) { console.log('mismatch: expected', top, 'got', tag, '->', m[0].slice(0,60)); }
  } else stack.push(tag.toLowerCase());
}
console.log('html unclosed:', stack.length ? stack.join(', ') : 'none');
